sections.syntax:
-- Toutes les colonnes :
SELECT * FROM nom_table;

-- Colonnes spécifiques :
SELECT colonne1, colonne2 FROM nom_table;

SELECT colonne1, colonne2
FROM nom_table
WHERE condition;

examples.code:
SELECT name, age
FROM Students
WHERE age > 21;

SELECT name, age, email
FROM Students
WHERE age >= 18 AND age <= 25;

-- Exemple avec OR :
SELECT * FROM Products
WHERE category = 'Electronics' OR price < 20;

SELECT product_name, price
FROM Products
WHERE price BETWEEN 10 AND 100;

-- Noms commençant par 'A' :
SELECT * FROM Students WHERE name LIKE 'A%';

-- Noms se terminant par 'son' :
SELECT * FROM Students WHERE name LIKE '%son';

-- Noms contenant 'ali' :
SELECT * FROM Students WHERE name LIKE '%ali%';

-- Trouver les employés sans département :
SELECT * FROM Employees WHERE department IS NULL;

-- Trouver les employés qui ONT un département :
SELECT * FROM Employees WHERE department IS NOT NULL;

sections.syntax:
SELECT colonne1, colonne2
FROM nom_table
ORDER BY colonne1 [ASC|DESC], colonne2 [ASC|DESC];

examples.code:
SELECT name, age
FROM Students
ORDER BY age ASC;

SELECT product_name, price
FROM Products
ORDER BY price DESC;

SELECT name, department, salary
FROM Employees
ORDER BY department ASC, salary DESC;

sections.syntax:
-- MySQL / PostgreSQL :
SELECT * FROM nom_table LIMIT n;
SELECT * FROM nom_table LIMIT n OFFSET décalage;

-- SQL Server :
SELECT TOP n * FROM nom_table;

examples.code:
-- Page 1 (lignes 1-10) :
SELECT * FROM Products ORDER BY product_id LIMIT 10 OFFSET 0;

-- Page 2 (lignes 11-20) :
SELECT * FROM Products ORDER BY product_id LIMIT 10 OFFSET 10;

-- Page 3 (lignes 21-30) :
SELECT * FROM Products ORDER BY product_id LIMIT 10 OFFSET 20;

SELECT DISTINCT city, country
FROM Customers
ORDER BY country, city;

sections.syntax:
-- Alias de colonne :
SELECT nom_colonne AS nom_alias FROM table;

-- Alias de table :
SELECT t.colonne FROM nom_table AS t;

SELECT colonne, FONCTION_AGGRÉGATION(autre_colonne)
FROM nom_table
GROUP BY colonne;

examples.code:
SELECT name, age
FROM Students
WHERE age > (SELECT AVG(age) FROM Students);

SELECT product_name
FROM Products
WHERE product_id NOT IN (
  SELECT DISTINCT product_id FROM OrderItems
);
